      { interval: "Immediately", timeLimit: "Unlimited", task: "Swirl Flap Delete", details: "CRITICAL: Remove the intake manifold, extract the plastic/metal flaps, and install aluminum blanking plates to prevent catastrophic engine ingestion.", parts: ["Blanking Plates", "Gaskets"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "250 EUR" },
      { interval: "Immediately", timeLimit: "Unlimited", task: "Exhaust Manifold Upgrade", details: "CRITICAL: If the cabin smells like exhaust, the factory stainless manifold has cracked. Remove it and install a heavy-duty cast iron unit.", parts: ["Cast Iron Manifold", "Gaskets/Nuts"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "400 EUR" },
      { interval: "150,000 km", timeLimit: "Unlimited", task: "Vibration Damper Replacement", details: "Proactively replace the main crankshaft pulley before the rubber core shears off and destroys the drive belts.", parts: ["Corteco Damper"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "250 EUR" },
      { interval: "As Needed", timeLimit: "Unlimited", task: "NOx Sensor / SCR Service (US Spec)", details: "If the check engine light illuminates for emissions on a US 35d, the highly sensitive NOx sensors or AdBlue tank heater often require expensive replacement.", parts: ["NOx Sensors / Tank"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "800+ EUR" }
