        { interval: "100,000 km", timeLimit: "8 years", task: "Glow Plugs & Relay Replacement", details: "Replace all 6 glow plugs and the relay module for reliable cold-weather starting. The module fails frequently.", parts: ["6x Plugs", "Relay"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "220 EUR" },
        { interval: "As Needed", timeLimit: "Unlimited", task: "CP3 Fuel Pump Retrofit", details: "Highly recommended to proactively remove the CP4 pump and install a CP3 conversion kit to prevent metal shaving contamination of the entire fuel system.", parts: ["CP3 Pump", "Retrofit Kit"], importance: "High", laborDifficulty: "Expert", estimatedCost: "1,200 EUR" }
