        { interval: "30,000 km", timeLimit: "3 years", task: "Engine Air Filter", details: "Replace the panel filter to protect the tri-turbos.", parts: ["Air Filter"], importance: "High", laborDifficulty: "Easy", estimatedCost: "25 EUR" },
        { interval: "15,000 km", timeLimit: "1.5 years", task: "Diesel Fuel Filter", details: "CRITICAL: Replace incredibly frequently to protect the notoriously fragile CP4.2 high-pressure fuel pump from any contamination.", parts: ["Fuel Filter"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "40 EUR" },
        { interval: "30,000 km", timeLimit: "2 years", task: "Cabin Microfilter", details: "Replace the interior cabin filter.", parts: ["Cabin Filter"], importance: "Low", laborDifficulty: "Easy", estimatedCost: "40 EUR" }
