      { interval: "80,000 km", timeLimit: "8 years", task: "Fuel Filter", details: "Integrated into the low-pressure fuel pump assembly inside the tank. Rarely serviced unless issues arise.", parts: ["In-Tank Assembly"], importance: "Low", laborDifficulty: "Advanced", estimatedCost: "200 EUR" },
      { interval: "30,000 km", timeLimit: "2 years", task: "Cabin Microfilter", details: "Replace the dual interior cabin filters.", parts: ["Cabin Filters"], importance: "Low", laborDifficulty: "Easy", estimatedCost: "40 EUR" }
