    { partName: "Coolant Expansion Tank Cap", category: "Cooling", oem: { brand: "BMW Genuine", code: "17117639020", approxPrice: "25 EUR" }, crossRef: { brand: "Mahle", code: "CRB 44 000S", approxPrice: "12 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.co.uk/spares-search?keyword=17117639020", advanceautopartslink: "https://shop.advanceautoparts.com/web/SearchResults?searchTerm=17117639020" }, note: "Replaces weak factory cap." }
