  engineeringData: { blockDesign: "Inline-6, Closed-deck Aluminum block with wire-arc sprayed cylinder liners. The B57 is a masterpiece of modern diesel engineering. The closed-deck design provides extreme rigidity, optimized for ultra-low NVH and strict Euro 6d emissions targets.", crankshaft: "Forged Steel, supported by 7 main bearings. Inherently perfectly balanced, resulting in a buttery-smooth inline-6 experience.", pistonSpeed: "14.4 m/s @ 4000 RPM.", alternator: "180A Valeo.", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy with integrated cooling galleries. Features a 16.5:1 compression ratio.", wristPinDiameter: "30 mm.", connectingRodLength: "135 mm.", rodBoltSize: "M10.", crankMainJournal: "60.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.53." }, cylinderHead: { combustionChamberVol: "Direct injection bowl-in-piston design with high-swirl intake ports.", intakePortFlow: "24-valve DOHC design. The intake tracts are prone to rapid carbon clogging from the EGR system.", valveSizes: "Intake: 27.2 mm / Exhaust: 27.2 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Standard diesel duration. Driven by a rear-mounted, heavily reinforced timing chain.", lifterType: "Hydraulic bucket tappets.", specialFeature: "Tax Dodge Variant (Fleet). This specific model is tailored for markets with heavy taxes above certain power thresholds (often Belgium). It is mechanically 100% identical to the global 265hp version, simply rated at 211hp on paper to slide under penalty brackets. This makes it the ultimate sleeper once tuned. The B57 is famous for finally solving the catastrophic timing chain snapping issues that plagued the older N57 engine." }, oilAndCooling: { oilSquirters: "Yes, high-pressure under-piston cooling jets.", oilPumpType: "Chain-driven variable displacement map-controlled pump.", thermostatOpening: "88°C Mechanical thermostat.", oilCooler: "Heavy-duty integrated heat exchanger." }, fuelSystem: { systemType: "Bosch Common Rail Direct Injection.", maxPressure: "2,500 Bar (Fuel Rail). Extremely high pressure required for Euro 6 emissions.", injectors: "6x Bosch Solenoid Injectors." }, tuningLimits: { maxSafeTorqueStock: "750 Nm (The heavy-duty ZF 8HP75 transmission handles this effortlessly).", maxSafePowerStock: "400 hp (The B57 block handles this power level easily).", maxSafeRPM: "4800 RPM", weakestLink: "EGR Cooler (Fire Risk), SCR System (NOx Sensors), Vibration Damper (Tears)." }, electrical: { coils: "N/A (Compression Ignition).", ecu: "Bosch DDE8 (Highly tunable via OBD)." } },
  recommendedParts: { description: "Crucial maintenance parts to prevent the EGR, SCR, and cooling failures inherent to the modern B57 diesel.", parts: [ { category: "EGR Cooler", brand: "BorgWarner / Genuine BMW", note: "CRITICAL: Ensure the latest revised unit is installed to prevent fires." }, { category: "NOx Sensor (Front)", brand: "Genuine BMW", note: "Common failure point in Euro 6 exhaust systems." }, { category: "Diesel Fuel Filter", brand: "Mann Filter", note: "Replace every 30k km to protect the 2500-bar fuel system." }, { category: "Vibration Damper", brand: "Corteco", note: "CRITICAL: Must replace proactively around 150k km." }, { category: "AdBlue Metering Valve", brand: "Bosch", note: "Replace or clean if crystallization causes SCR faults." }, { category: "Glow Plugs & Relay", brand: "Bosch / Beru", note: "Essential for reliable winter starts and DPF regens." }, { category: "Intake Manifold Gaskets", brand: "Elring", note: "Required when performing mandatory Walnut Blasting." }, { category: "Front Thrust Arms (Control Arms)", brand: "Lemförder", note: "Fixes severe G05 braking shimmy." } ] },
