      { interval: "80,000 km", timeLimit: "Unlimited", task: "Intake Manifold Walnut Blasting", details: "Clear the thick carbon sludge from the intake ports caused by the EGR.", parts: ["Intake Gaskets", "Labor"], importance: "High", laborDifficulty: "Expert", estimatedCost: "350 EUR" },
      { interval: "100,000 km", timeLimit: "8 years", task: "Glow Plugs & Relay Replacement", details: "Replace all 6 glow plugs and the module. Essential for triggering DPF regens.", parts: ["6x Plugs", "Relay"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "220 EUR" },
      { interval: "150,000 km", timeLimit: "Unlimited", task: "Vibration Damper Replacement", details: "Proactively replace the main crankshaft pulley before it fails.", parts: ["Corteco Damper"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "250 EUR" },
      { interval: "As Needed", timeLimit: "Unlimited", task: "NOx Sensor / SCR Service", details: "If the check engine light illuminates for emissions, the highly sensitive NOx sensors or AdBlue metering valve often require replacement.", parts: ["NOx Sensors"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "600+ EUR" },
      { interval: "5 Years", timeLimit: "5 years", task: "48V Battery Service", details: "CRITICAL: The dedicated 48V battery under the hood degrades. If it fails, the MHEV system disables the car.", parts: ["48V Lithium Battery"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "800+ EUR" }
