      { interval: "Immediately", timeLimit: "Unlimited", task: "Oil Filter Housing Upgrade", details: "CRITICAL: Proactively replace the brittle factory plastic oil filter housing with a CNC billet aluminum unit BEFORE it cracks and mixes oil with coolant.", parts: ["Billet OFH"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "450 EUR" },
      { interval: "Immediately", timeLimit: "Unlimited", task: "Charge Pipe Upgrade", details: "CRITICAL: Proactively replace the plastic charge pipe with an aluminum unit to prevent boost leaks and stranding.", parts: ["Aluminum Charge Pipe"], importance: "Critical", laborDifficulty: "Intermediate", estimatedCost: "250 EUR" },
      { interval: "As Needed", timeLimit: "Unlimited", task: "Coolant Flange & Expansion Tank Cap", details: "CRITICAL: If mysterious coolant loss occurs, replace the plastic cylinder head flange with a billet unit and replace the expansion tank cap.", parts: ["Billet Flange", "OEM Cap"], importance: "High", laborDifficulty: "Easy", estimatedCost: "50 EUR" },
      { interval: "120,000 km", timeLimit: "Unlimited", task: "Intake Manifold Walnut Blasting", details: "Remove the intake manifold (with integrated intercooler) and blast the thick carbon sludge from the intake ports caused by direct injection.", parts: ["Intake Gaskets", "Labor"], importance: "Medium", laborDifficulty: "Expert", estimatedCost: "400 EUR" },
      { interval: "100,000 km", timeLimit: "8 years", task: "Valve Cover Replacement", details: "Replace the entire plastic valve cover. The gasket leaks oil, and the integrated PCV membrane fails, causing huge vacuum leaks.", parts: ["Valve Cover Assembly"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "450 EUR" },
      { interval: "50,000 km", timeLimit: "5 years", task: "Spark Plug Replacement", details: "Direct-injected turbo engines eat spark plugs. Replace to prevent severe misfires under heavy boost.", parts: ["6x NGK Plugs"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "120 EUR" },
      { interval: "100,000 km", timeLimit: "8 years", task: "Ignition Coil Replacement", details: "Proactively replace coil packs to maintain perfectly smooth power delivery.", parts: ["6x Eldor/Bosch Coils"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "240 EUR" }
